INSERT INTO `creature_template_locale` (`entry`, `locale`, `Name`) SELECT incoming.entry, incoming.locale, incoming.translation FROM (SELECT `entry`, 'ruRU' AS locale, CONVERT(X'd094d0b0d180d0bdd0b5d0bbd0bb' USING utf8mb4) AS translation FROM `creature_template` AS b WHERE b.`entry`=49425 AND (BINARY b.`name` <=> BINARY CONVERT(X'4461726e656c6c' USING utf8mb4))) AS incoming ON DUPLICATE KEY UPDATE `Name`=IF(BINARY `creature_template_locale`.`locale`='ruRU' AND (`creature_template_locale`.`Name` IS NULL OR OCTET_LENGTH(`creature_template_locale`.`Name`)=0), incoming.translation, `creature_template_locale`.`Name`);
